<div class="d-flex flex-wrap gap-2 align-items-center mb-3 sticky-top bg-body py-2 take-bar"><h2 class="h5 mb-0"><?= e($a['title']) ?></h2><?php if ($a['remaining'] !== null): ?><span class="badge text-bg-danger fs-6 ms-auto" id="timer" data-remaining="<?= (int)$a['remaining'] ?>" role="timer" aria-live="off">--:--</span><?php endif; ?><span class="small text-muted" id="saveState"></span></div>
<form id="takeForm" data-answer-url="<?= url('api/v1/learn/attempts/' . (int)$a['id'] . '/answer') ?>" data-submit-url="<?= url('api/v1/learn/attempts/' . (int)$a['id'] . '/submit') ?>"><?= csrf_field() ?>
<?php foreach ($a['questions'] as $i => $q): $n = (int)$q['id']; $sv = $q['saved']; ?><div class="card-s mb-3 qblock" data-qid="<?= $n ?>" data-kind="<?= e($q['kind']) ?>"><div class="d-flex gap-2"><strong><?= $i + 1 ?>.</strong><div class="flex-grow-1"><span class="math-content"><?= e($q['body']) ?></span> <span class="badge text-bg-secondary"><?= (float)$q['points'] ?> د</span><?= qimg(!empty($q['image_file_id']) ? (int)$q['image_file_id'] : null) ? '<div class="mt-2">' . qimg((int)$q['image_file_id']) . '</div>' : '' ?></div></div><div class="mt-2">
  <?php if ($q['kind'] === 'mcq'): foreach ($q['options'] as $k => $o): ?><div class="form-check"><input class="form-check-input" type="radio" name="q<?= $n ?>" id="q<?= $n ?>_<?= $k ?>" value="<?= $k ?>" <?= $sv === $k ? 'checked' : '' ?>><label class="form-check-label" for="q<?= $n ?>_<?= $k ?>"><?= qopt($q, $k) ?></label></div><?php endforeach;
  elseif ($q['kind'] === 'true_false'): foreach ([['true', 'صح', true], ['false', 'خطأ', false]] as [$v, $l, $b]): ?><div class="form-check form-check-inline"><input class="form-check-input" type="radio" name="q<?= $n ?>" id="q<?= $n ?>_<?= $v ?>" value="<?= $v ?>" <?= $sv === $b ? 'checked' : '' ?>><label class="form-check-label" for="q<?= $n ?>_<?= $v ?>"><?= $l ?></label></div><?php endforeach;
  elseif ($q['kind'] === 'short'): ?><input class="form-control" name="q<?= $n ?>" value="<?= e($sv) ?>" maxlength="500" aria-label="إجابتك" autocomplete="off"><?php else: ?><textarea class="form-control" name="q<?= $n ?>" rows="5" maxlength="5000" aria-label="إجابتك"><?= e($sv) ?></textarea><?php endif; ?></div></div><?php endforeach; ?>
<button class="btn btn-success btn-lg" type="submit" id="finish">تسليم الاختبار</button></form>
